import {zoneClock,zoneRange,aggregateZones,zoneShares,zoneAt,zoneDate} from './zone-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const zoneDuration=v=>Math.round(v)>=3600?Math.floor(Math.round(v)/3600)+'h '+Math.floor(Math.round(v)%3600/60)+'m':zoneClock(v);
export function zoneChart(d,{title,setting=null,aggregate=false}={}){
 if(!d?.knownS)return '';
 const peak=d.bins.reduce((a,b)=>b.seconds>a.seconds?b:a),shares=zoneShares(d.bins),percent=b=>shares[b.zone-1];
 return `<section class="zn-chart zn-${d.kind}" aria-label="${esc(title)}"><div class="zn-heading"><h2>${esc(title)}</h2><a href="/account?zones=${d.kind}#running-zones">Edit zones</a></div><p class="zn-conclusion"><strong>${percent(peak)}% in Zone ${peak.zone}.</strong> ${zoneDuration(peak.seconds)} of ${zoneDuration(d.knownS)} measured.</p><table><caption class="sr-only">Recorded time in your ${d.kind==='heart'?'heart-rate':'pace'} zones</caption><colgroup><col class="zn-zone-col"><col><col class="zn-time-col"><col class="zn-share-col"></colgroup><thead class="sr-only"><tr><th scope="col">Zone and range</th><th scope="col">Time bar</th><th scope="col">Time</th><th scope="col">Share</th></tr></thead><tbody>${d.bins.toReversed().map(b=>`<tr><th scope="row"><span>Z${b.zone}</span>${setting?`<small>${esc(zoneRange(setting,b.zone-1))}${d.kind==='heart'?' bpm':' /km'}</small>`:''}</th><td class="zn-bar"><i style="width:${b.seconds/d.knownS*100}%" aria-hidden="true"></i></td><td class="zn-duration">${zoneDuration(b.seconds)}</td><td>${percent(b)}%</td></tr>`).join('')}</tbody></table><details class="zn-method"><summary>View coverage and settings</summary><p>${aggregate?`${d.sampledRuns} ${d.sampledRuns===1?'run':'runs'} with usable samples${d.uncoveredRuns?` · ${d.uncoveredRuns} without matching settings or samples`:''}. ${d.revisions.length} ${d.revisions.length===1?'settings version':'settings versions'} used, as effective on each run.`:`Settings v${d.settingRevision} · effective ${esc(zoneDate(d.effectiveFrom))}.`}${d.unknownS?` ${zoneDuration(d.unknownS)} without usable samples.`:''} Time follows each recorded sample for up to 15 seconds. Gaps stay unclassified. Pace boundaries belong to the faster zone; heart-rate boundaries belong to the higher zone.</p></details></section>`;
}

export function progressZonesMarkup(sessions,kind='heart',{versions=[],through='9999-12-31'}={}){
 const data=aggregateZones(sessions,kind),setting=data.revisions.length===1?data.settings.find(s=>s.settingRevision===data.revisions[0]):null;
 const active=zoneAt(versions,kind,through),hasSettings=Boolean(active?.boundaries),label=kind==='heart'?'heart-rate':'pace';
 const tabs=`<div class="zn-tabs" role="group" aria-label="Progress zone measurement">${[['heart','Heart rate'],['pace','Pace']].map(([k,l])=>`<button type="button" data-progress-zone="${k}" aria-pressed="${kind===k}">${l}</button>`).join('')}</div>`;
 return `${tabs}${data.knownS?zoneChart(data,{title:kind==='heart'?'Your heart-rate zones':'Your pace zones',setting,aggregate:true}):`<div class="zn-heading"><h2>Time in your zones</h2><a href="/account?zones=${kind}#running-zones">${hasSettings?'Edit zones':'Set your zones'}</a></div><p class="zn-empty">${hasSettings?`No usable ${label} samples in these runs yet. Summary-only imports keep their original totals.`:'Add your zone boundaries in Account to see your effort here. Choose an effective date covering your runs.'}</p>`}`;
}
